public int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int need = target - nums[i];
        if (seen.containsKey(need)) {
            return new int[]{seen.get(need), i}; } seen.put(nums[i], i);
    } return new int[]{}; }

public boolean isValid(String s) { Deque<Character> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) { if (c == '(' || c == '[' || c == '{') { stack.push(c); } else { if (stack.isEmpty()) return false;
            char top = stack.pop();
            if (c == ')' && top != '(') return false;
            if (c == ']' && top != '[') return false;
            if (c == '}' && top != '{') return false; } }
    return stack.isEmpty(); }

class ListNode { int val;
    ListNode next;
    ListNode(int val) { this.val = val; } } public ListNode reverseList(ListNode head) { ListNode prev = null;
    while (head != null) { ListNode next = head.next;
        head.next = prev;
        prev = head;
        head = next; } return prev; }

public int maxSubArray(int[] nums) {
    int best = nums[0], cur = nums[0];
    for (int i = 1; i < nums.length; i++) {
        cur = Math.max(nums[i], cur + nums[i]);
        best = Math.max(best, cur);
    } return best;
}

class ListNode { int val;
    ListNode next;
    ListNode(int val) { this.val = val; } } public ListNode mergeTwoLists(ListNode a, ListNode b) { ListNode dummy = new ListNode(0), tail = dummy;
    while (a != null && b != null) { if (a.val <= b.val) { tail.next = a;
            a = a.next; } else { tail.next = b;
            b = b.next; } tail = tail.next; } tail.next = (a != null) ? a : b;
    return dummy.next; }

public int maxProfit(int[] prices) {
    int best = 0, low = prices[0];
    for (int price : prices) {
        best = Math.max(best, price - low);
        low = Math.min(low, price);
    } return best;
}

public boolean isPalindrome(String s) { int left = 0, right = s.length() - 1;
    while (left < right) {
        while (left < right && !Character.isLetterOrDigit(s.charAt(left))) left++;
        while (left < right && !Character.isLetterOrDigit(s.charAt(right))) right--;
        if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {
            return false; } left++;
        right--; } return true; }

public int climbStairs(int n) { int a = 1, b = 1;
    for (int i = 0; i < n - 1; i++) {
        int temp = a + b;
        a = b;
        b = temp;
    } return b;
}

public int binarySearch(int[] arr, int target) {
    int lo = 0, hi = arr.length - 1;
    while (lo <= hi) { int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    } return -1; }

public int singleNumber(int[] nums) {
    int result = 0;
    for (int n : nums) {
        result ^= n;
    }
    return result;
}

public boolean containsDuplicate(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    for (int n : nums) {
        if (!seen.add(n)) return true;
    }
    return false;
}

public int majorityElement(int[] nums) {
    int count = 0, candidate = 0;
    for (int n : nums) {
        if (count == 0) candidate = n;
        count += (n == candidate) ? 1 : -1;
    } return candidate;
}

public void moveZeroes(int[] nums) {
    int write = 0;
    for (int n : nums) {
        if (n != 0) nums[write++] = n;
    }
    while (write < nums.length) nums[write++] = 0;
}

public int[] productExceptSelf(int[] nums) { int n = nums.length;
    int[] res = new int[n];
    res[0] = 1;
    for (int i = 1; i < n; i++) { res[i] = res[i - 1] * nums[i - 1];
    } int right = 1;
    for (int i = n - 1; i >= 0; i--) { res[i] *= right;
        right *= nums[i]; } return res; }

public int[][] merge(int[][] intervals) { Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
    List<int[]> merged = new ArrayList<>();
    for (int[] interval : intervals) {
        if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) { merged.add(interval);
        } else { merged.get(merged.size() - 1)[1] =
                Math.max(merged.get(merged.size() - 1)[1], interval[1]); } }
    return merged.toArray(new int[merged.size()][]); }

public List<List<String>> groupAnagrams(String[] strs) {
    Map<String, List<String>> groups = new HashMap<>();
    for (String s : strs) { char[] chars = s.toCharArray();
        Arrays.sort(chars);
        String key = new String(chars);
        groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
    } return new ArrayList<>(groups.values()); }

public String longestCommonPrefix(String[] strs) {
    String prefix = strs[0];
    for (String s : strs) { while (!s.startsWith(prefix)) {
            prefix = prefix.substring(0, prefix.length() - 1);
            if (prefix.isEmpty()) return "";
        } }
    return prefix; }

public int romanToInt(String s) { Map<Character, Integer> values = new HashMap<>();
    values.put('I', 1); values.put('V', 5); values.put('X', 10); values.put('L', 50);
    values.put('C', 100); values.put('D', 500);
    values.put('M', 1000); int total = 0;
    for (int i = 0; i < s.length(); i++) { int value = values.get(s.charAt(i));
        if (i + 1 < s.length() && value < values.get(s.charAt(i + 1))) { total -= value; } else { total += value; } }
    return total; }

public boolean isPalindrome(int x) {
    if (x < 0 || (x % 10 == 0 && x != 0)) return false;
    int reversed = 0;
    while (x > reversed) { reversed = reversed * 10 + x % 10;
        x /= 10;
    } return x == reversed || x == reversed / 10;
}

public int[] plusOne(int[] digits) {
    for (int i = digits.length - 1; i >= 0; i--) { if (digits[i] < 9) { digits[i]++;
            return digits;
        } digits[i] = 0;
    } int[] result = new int[digits.length + 1];
    result[0] = 1;
    return result; }

public int removeDuplicates(int[] nums) { int write = 0;
    for (int n : nums) {
        if (write == 0 || n != nums[write - 1]) {
            nums[write++] = n;
        } }
    return write;
}

public void rotate(int[] nums, int k) { int n = nums.length;
    k %= n;
    reverse(nums, 0, n - 1);
    reverse(nums, 0, k - 1);
    reverse(nums, k, n - 1); } private void reverse(int[] nums, int left, int right) { while (left < right) { int temp = nums[left];
        nums[left++] = nums[right];
        nums[right--] = temp; } }

public int missingNumber(int[] nums) {
    int n = nums.length;
    int total = n * (n + 1) / 2;
    for (int num : nums) {
        total -= num;
    } return total;
}

public List<String> fizzBuzz(int n) {
    List<String> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) { if (i % 15 == 0) result.add("FizzBuzz");
        else if (i % 3 == 0) result.add("Fizz");
        else if (i % 5 == 0) result.add("Buzz");
        else result.add(String.valueOf(i));
    } return result; }

public boolean isPowerOfTwo(int n) {
    return n > 0 && (n & (n - 1)) == 0;
}

public int hammingWeight(int n) {
    int count = 0;
    while (n != 0) {
        count += n & 1;
        n >>>= 1;
    } return count;
}

public void reverseString(char[] s) {
    int left = 0, right = s.length - 1;
    while (left < right) {
        char temp = s[left];
        s[left++] = s[right];
        s[right--] = temp;
    } }

public int reverse(int x) { long result = 0;
    while (x != 0) {
        result = result * 10 + x % 10;
        x /= 10;
    } if (result < Integer.MIN_VALUE || result > Integer.MAX_VALUE) return 0;
    return (int) result;
}

public int lengthOfLastWord(String s) { int length = 0;
    int i = s.length() - 1;
    while (i >= 0 && s.charAt(i) == ' ') i--;
    while (i >= 0 && s.charAt(i) != ' ') { length++;
        i--;
    } return length;
}

public int strStr(String haystack, String needle) {
    if (needle.isEmpty()) return 0;
    for (int i = 0; i <= haystack.length() - needle.length(); i++) {
        if (haystack.startsWith(needle, i)) return i;
    }
    return -1;
}

public String addBinary(String a, String b) { StringBuilder result = new StringBuilder();
    int i = a.length() - 1, j = b.length() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry > 0) { int total = carry;
        if (i >= 0) total += a.charAt(i--) - '0';
        if (j >= 0) total += b.charAt(j--) - '0';
        result.append(total % 2);
        carry = total / 2; } return result.reverse().toString(); }

public int mySqrt(int x) { if (x < 2) return x;
    int lo = 1, hi = x / 2, answer = 0;
    while (lo <= hi) { int mid = lo + (hi - lo) / 2;
        if ((long) mid * mid <= x) { answer = mid;
            lo = mid + 1;
        } else { hi = mid - 1; } }
    return answer; }

public int titleToNumber(String columnTitle) {
    int result = 0;
    for (char c : columnTitle.toCharArray()) {
        result = result * 26 + (c - 'A' + 1);
    }
    return result;
}

public boolean isHappy(int n) { Set<Integer> seen = new HashSet<>();
    while (n != 1 && seen.add(n)) { int total = 0;
        while (n > 0) { int digit = n % 10;
            total += digit * digit;
            n /= 10;
        } n = total;
    } return n == 1; }

public boolean isIsomorphic(String s, String t) { int[] forward = new int[256];
    int[] backward = new int[256];
    for (int i = 0; i < s.length(); i++) { char a = s.charAt(i), b = t.charAt(i);
        if (forward[a] == 0) forward[a] = b;
        if (backward[b] == 0) backward[b] = a;
        if (forward[a] != b || backward[b] != a) return false;
    } return true; }

public boolean wordPattern(String pattern, String s) { String[] words = s.split(" ");
    if (pattern.length() != words.length) return false;
    Map<Character, String> forward = new HashMap<>(); Map<String, Character> backward = new HashMap<>();
    for (int i = 0; i < words.length; i++) { char c = pattern.charAt(i);
        if (forward.containsKey(c) && !forward.get(c).equals(words[i])) return false;
        if (backward.containsKey(words[i]) && backward.get(words[i]) != c) return false;
        forward.put(c, words[i]); backward.put(words[i], c); } return true; }

public int[] intersection(int[] nums1, int[] nums2) { Set<Integer> set = new HashSet<>();
    for (int n : nums1) set.add(n);
    List<Integer> result = new ArrayList<>();
    for (int n : nums2) { if (set.remove(n)) result.add(n);
    } int[] out = new int[result.size()];
    for (int i = 0; i < out.length; i++) out[i] = result.get(i);
    return out; }

public int[] sortedSquares(int[] nums) { int n = nums.length;
    int[] result = new int[n];
    int left = 0, right = n - 1;
    for (int i = n - 1; i >= 0; i--) { if (Math.abs(nums[left]) > Math.abs(nums[right])) { result[i] = nums[left] * nums[left];
            left++; } else { result[i] = nums[right] * nums[right];
            right--; } }
    return result; }

class TreeNode { int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
} public int maxDepth(TreeNode root) { if (root == null) return 0;
    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}

class TreeNode { int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
} public boolean isSameTree(TreeNode p, TreeNode q) { if (p == null && q == null) return true;
    if (p == null || q == null || p.val != q.val) return false;
    return isSameTree(p.left, q.left) && isSameTree(p.right, q.right); }

class TreeNode { int val;
    TreeNode left; TreeNode right;
    TreeNode(int val) { this.val = val; } } public TreeNode invertTree(TreeNode root) { if (root == null) return null;
    TreeNode left = invertTree(root.left);
    root.left = invertTree(root.right);
    root.right = left;
    return root; }

class TreeNode { int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; } } public boolean isSymmetric(TreeNode root) { return root == null || mirror(root.left, root.right);
} private boolean mirror(TreeNode a, TreeNode b) { if (a == null && b == null) return true;
    if (a == null || b == null || a.val != b.val) return false;
    return mirror(a.left, b.right) && mirror(a.right, b.left); }

class TreeNode { int val; TreeNode left; TreeNode right;
    TreeNode(int val) { this.val = val; } } private int diameter = 0;
public int diameterOfBinaryTree(TreeNode root) { depth(root);
    return diameter; } private int depth(TreeNode node) { if (node == null) return 0;
    int left = depth(node.left); int right = depth(node.right);
    diameter = Math.max(diameter, left + right);
    return 1 + Math.max(left, right); }

class TreeNode { int val;
    TreeNode left; TreeNode right;
    TreeNode(int val) { this.val = val; } } public boolean isBalanced(TreeNode root) { return height(root) >= 0; } private int height(TreeNode node) { if (node == null) return 0;
    int left = height(node.left);
    int right = height(node.right);
    if (left < 0 || right < 0 || Math.abs(left - right) > 1) return -1;
    return 1 + Math.max(left, right); }

class TreeNode { int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; } } public boolean hasPathSum(TreeNode root, int targetSum) { if (root == null) return false;
    if (root.left == null && root.right == null) return root.val == targetSum;
    return hasPathSum(root.left, targetSum - root.val)
        || hasPathSum(root.right, targetSum - root.val); }

class TreeNode { int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
} public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) { while (root != null) { if (p.val < root.val && q.val < root.val) { root = root.left;
        } else if (p.val > root.val && q.val > root.val) { root = root.right; } else { return root; } }
    return null; }

public int searchInsert(int[] nums, int target) {
    int lo = 0, hi = nums.length;
    while (lo < hi) { int mid = lo + (hi - lo) / 2;
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid;
    } return lo;
}

public int[] twoSumSorted(int[] numbers, int target) {
    int left = 0, right = numbers.length - 1;
    while (left < right) {
        int total = numbers[left] + numbers[right];
        if (total == target) return new int[]{left + 1, right + 1}; if (total < target) left++;
        else right--;
    } return new int[]{}; }

public int lengthOfLongestSubstring(String s) { Map<Character, Integer> last = new HashMap<>();
    int start = 0, best = 0;
    for (int i = 0; i < s.length(); i++) { char c = s.charAt(i);
        if (last.containsKey(c) && last.get(c) >= start) { start = last.get(c) + 1;
        } last.put(c, i);
        best = Math.max(best, i - start + 1);
    } return best; }

public int maxArea(int[] height) {
    int left = 0, right = height.length - 1, best = 0;
    while (left < right) {
        best = Math.max(best, Math.min(height[left], height[right]) * (right - left));
        if (height[left] < height[right]) left++;
        else right--;
    } return best; }
